using System;
using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;
using System.Threading;
using Microsoft.CodeAnalysis;
using WindowsRuntime.InteropGenerator.Helpers;

#pragma warning disable IDE0072

namespace WindowsRuntime.SourceGenerator;

/// <summary>
/// Computes Windows Runtime type signatures from compiler-visible metadata, matching the ones generated by the interop generator.
/// </summary>
/// <param name="metadata">The resolver for the metadata of the types to compute signatures for.</param>
/// <param name="token">The cancellation token.</param>
internal sealed class WindowsRuntimeSignatureGenerator(
    WindowsRuntimeMetadataResolver metadata,
    CancellationToken token)
{
    /// <summary>
    /// Guards against malformed recursive value metadata.
    /// </summary>
    private readonly HashSet<ITypeSymbol> _activeTypes = new(SymbolEqualityComparer.Default);

    /// <summary>
    /// Computes a supported Windows Runtime parameter signature.
    /// </summary>
    /// <param name="type">The input type.</param>
    /// <param name="useWindowsUIXamlProjections">Whether to use UWP XAML mappings.</param>
    /// <param name="signature">The resulting signature.</param>
    /// <returns>Whether sufficient, valid metadata is available.</returns>
    public bool TryGetSignature(
        ITypeSymbol type,
        bool useWindowsUIXamlProjections,
        [NotNullWhen(true)] out string? signature)
    {
        token.ThrowIfCancellationRequested();

        // Metadata can be cyclic (e.g. a struct containing itself through a generic, or a runtime class whose default interface
        // is generic over the class), so stop if this type is already being resolved higher up in the call stack.
        if (!_activeTypes.Add(type))
        {
            signature = null;

            return false;
        }

        bool success = TryGetSignatureCore(type, useWindowsUIXamlProjections, out signature);

        _ = _activeTypes.Remove(type);

        return success;
    }

    /// <summary>
    /// Tries to get the Windows Runtime signature of a fundamental type (a primitive, <see cref="string"/>, or <see cref="object"/>).
    /// </summary>
    /// <param name="type">The input type.</param>
    /// <param name="signature">The resulting signature, if <paramref name="type"/> is a fundamental type.</param>
    /// <returns>Whether <paramref name="type"/> is a fundamental type.</returns>
    private static bool TryGetFundamentalTypeSignature(ITypeSymbol type, [NotNullWhen(true)] out string? signature)
    {
        signature = type.SpecialType switch
        {
            SpecialType.System_Boolean => "b1",
            SpecialType.System_Byte => "u1",
            SpecialType.System_Char => "c2",
            SpecialType.System_Int16 => "i2",
            SpecialType.System_UInt16 => "u2",
            SpecialType.System_Int32 => "i4",
            SpecialType.System_UInt32 => "u4",
            SpecialType.System_Int64 => "i8",
            SpecialType.System_UInt64 => "u8",
            SpecialType.System_Single => "f4",
            SpecialType.System_Double => "f8",
            SpecialType.System_String => "string",
            SpecialType.System_Object => "cinterface(IInspectable)",
            _ => null
        };

        return signature is not null;
    }

    /// <inheritdoc cref="TryGetSignature"/>
    private bool TryGetSignatureCore(
        ITypeSymbol type,
        bool useWindowsUIXamlProjections,
        [NotNullWhen(true)] out string? signature)
    {
        // 'dynamic' is not a statically-visible type that we can resolve, so it has no signature (it would otherwise look like 'object')
        if (type.TypeKind == TypeKind.Dynamic)
        {
            signature = null;

            return false;
        }

        // Primitives, 'string' and 'object' have fixed signatures
        if (TryGetFundamentalTypeSignature(type, out signature))
        {
            return true;
        }

        // Single-dimensional arrays are 'IReferenceArray<T>' (nested arrays are not supported)
        if (type is IArrayTypeSymbol { IsSZArray: true, ElementType: not IArrayTypeSymbol } array &&
            TryGetSignature(array.ElementType, useWindowsUIXamlProjections, out string? elementSignature))
        {
            signature = $"pinterface({{61c17707-2d65-11e0-9ae8-d48564015472}};{elementSignature})";

            return true;
        }

        // Anything else needs a type with Windows Runtime metadata, which also gives us its metadata name
        if (!metadata.TryGetDefinition(type, out INamedTypeSymbol? definition, out string? name))
        {
            return false;
        }

        // 'Guid' is a fundamental type in Windows Runtime signatures, but it's a struct in managed code
        if (name == "System.Guid")
        {
            signature = "g16";

            return true;
        }

        // Custom-mapped types (e.g. 'Uri' or 'DateTimeOffset') use the signature of their Windows Runtime counterpart
        if (TypeMapping.TryFindMappedTypeSignature(name, useWindowsUIXamlProjections, out signature))
        {
            return true;
        }

        // Closed generic types are parameterized, so their signature is built from the definition and all type arguments
        if (type is INamedTypeSymbol { IsGenericType: true } genericType)
        {
            return TryGetGenericSignature(genericType, name, useWindowsUIXamlProjections, out signature);
        }

        // Interfaces and delegates are identified by their IID, with a 'delegate(...)' wrapper for the latter
        if (metadata.TryGetDefinitionIid(definition, name, useWindowsUIXamlProjections, out Guid iid))
        {
            signature = definition.TypeKind == TypeKind.Delegate ? $"delegate({{{iid}}})" : $"{{{iid}}}";

            return true;
        }

        // The default interface is often exclusive-to, so it is recorded by name and not among the class's interfaces
        if (definition.TypeKind == TypeKind.Class &&
            metadata.TryGetDefaultInterface(definition, name, out INamedTypeSymbol? defaultInterface) &&
            TryGetSignature(defaultInterface, useWindowsUIXamlProjections, out string? defaultInterfaceSignature))
        {
            signature = $"rc({name};{defaultInterfaceSignature})";

            return true;
        }

        // Enums are identified by name and underlying type, which is either 'int' (the default) or 'uint' (flags)
        if (definition.TypeKind == TypeKind.Enum)
        {
            string underlyingTypeSignature = definition.EnumUnderlyingType?.SpecialType == SpecialType.System_UInt32 ? "u4" : "i4";

            signature = $"enum({name};{underlyingTypeSignature})";

            return true;
        }

        // Structs have a signature built from the signatures of all their fields, if they are all supported
        if (definition.TypeKind == TypeKind.Struct &&
            TryGetStructSignature(definition, name, useWindowsUIXamlProjections, out signature))
        {
            return true;
        }

        signature = null;

        return false;
    }

    /// <summary>
    /// Computes a signature for a supported closed generic type.
    /// </summary>
    /// <param name="type">The constructed type.</param>
    /// <param name="name">Its definition's metadata name.</param>
    /// <param name="useWindowsUIXamlProjections">Whether to use UWP XAML mappings.</param>
    /// <param name="signature">The resulting parameterized signature.</param>
    /// <returns>Whether the generic definition and all arguments are supported.</returns>
    private bool TryGetGenericSignature(
        INamedTypeSymbol type,
        string name,
        bool useWindowsUIXamlProjections,
        [NotNullWhen(true)] out string? signature)
    {
        // Only trust generic definitions that come from the runtime assembly or the framework, not same-named types
        if (!metadata.IsRuntimeOrFrameworkDefinition(type.OriginalDefinition, name))
        {
            signature = null;

            return false;
        }

        // The generic definition needs a known IID, which is the base of the parameterized IID
        if (!metadata.TryGetDefinitionIid(type.OriginalDefinition, name, useWindowsUIXamlProjections, out Guid definitionIid))
        {
            signature = null;

            return false;
        }

        // Nullable key/value pairs are not valid, as 'KeyValuePair<K, V>' already projects to a Windows Runtime interface
        if (type.OriginalDefinition.SpecialType == SpecialType.System_Nullable_T &&
            type.TypeArguments[0] is INamedTypeSymbol nullableArgument &&
            nullableArgument.OriginalDefinition.GetFullyQualifiedMetadataName() == "System.Collections.Generic.KeyValuePair`2")
        {
            signature = null;

            return false;
        }

        using PooledArrayBuilder<string> arguments = new();

        // Every generic argument needs a signature too (arrays are not supported as generic arguments)
        foreach (ITypeSymbol argument in type.TypeArguments)
        {
            if (argument is IArrayTypeSymbol ||
                !TryGetSignature(argument, useWindowsUIXamlProjections, out string? argumentSignature))
            {
                signature = null;

                return false;
            }

            arguments.Add(argumentSignature);
        }

        signature = $"pinterface({{{definitionIid}}};{string.Join(";", arguments.WrittenSpan)})";

        return true;
    }

    /// <summary>
    /// Computes a struct signature in metadata field order.
    /// </summary>
    /// <param name="type">The struct definition.</param>
    /// <param name="name">Its metadata name.</param>
    /// <param name="useWindowsUIXamlProjections">Whether to use UWP XAML mappings.</param>
    /// <param name="signature">The resulting value signature.</param>
    /// <returns>Whether every instance field has a supported signature.</returns>
    private bool TryGetStructSignature(
        INamedTypeSymbol type,
        string name,
        bool useWindowsUIXamlProjections,
        [NotNullWhen(true)] out string? signature)
    {
        signature = null;

        using PooledArrayBuilder<string> fields = new();

        // The signature of a struct is the concatenation of the signatures of each of its fields, in layout order
        foreach (ISymbol member in type.GetMembers())
        {
            if (member is not IFieldSymbol { IsStatic: false } field)
            {
                continue;
            }

            if (!TryGetSignature(field.Type, useWindowsUIXamlProjections, out string? fieldSignature))
            {
                return false;
            }

            fields.Add(fieldSignature);
        }

        // Windows Runtime structs can't be empty, so a struct with no instance fields is invalid
        if (fields.Count == 0)
        {
            return false;
        }

        signature = $"struct({name};{string.Join(";", fields.WrittenSpan)})";

        return true;
    }
}
